import { randomNumber } from "./randomNumber";
export function randomNumbers(size, minValue, maxValue) {
  if (!size || size <= 0 || size > Number.MAX_SAFE_INTEGER) {
    return undefined;
  }
  var result = [];
  for (var i = 0; i < size; i++) {
    var value = randomNumber(minValue, maxValue);
    if (!value) {
      break;
    }
    result.push(value);
  }
  return result;
}