export function forEachBreakable(callback) {
  if (!window.localStorage.length || !callback) {
    return;
  }
  for (var i = 0; i < window.localStorage.length; i++) {
    var _key = window.localStorage.key(i);
    if (_key) {
      if (!callback(window.localStorage.getItem(_key), _key)) {
        break;
      }
    }
  }
}