export function forEachIndexing(callback) {
  if (!window.sessionStorage.length || !callback) {
    return;
  }
  for (var i = 0; i < window.sessionStorage.length; i++) {
    var _key = window.sessionStorage.key(i);
    if (_key) {
      callback(window.sessionStorage.getItem(_key), _key, i);
    }
  }
}